   {
    "h": "60 mV/dec 與功耗牆",
    "b": "$$I_{\\text{off}} \\propto \\exp\\!\\left(\\frac{q(V_{GS}-V_{th})}{m\\,k_BT}\\right),\\qquad \\text{SS} = m(\\ln 10)\\frac{k_BT}{q}$$<b>讀法</b>：關閉時的漏電是源極裡「夠熱」的電子翻過能障。能障每降低一個 SS，漏電就多 10 倍。室溫 $k_BT/q \\approx 25.85\\ \\text{mV}$，就算體效應因子 $m=1$，SS 也有 $25.85\\times\\ln 10 \\approx 59.5\\ \\text{mV/dec}$。<br><br>所以 $V_{th}$ 只要降 $180\\ \\text{mV}$，在最理想的 $59.5\\ \\text{mV/dec}$ 下漏電就約多 $10^{180/59.5}\\approx 1056$ 倍。$V_{th}$ 只好停在約 $0.2\\text{–}0.3\\ \\text{V}$，$V_{DD}$ 也就很難低於約 $0.65\\text{–}0.75\\ \\text{V}$。再加上 $\\mathrm{SiO_2}$ 閘極氧化層薄到約 $1.2\\ \\text{nm}$ 以下時直接穿隧漏電急升，電壓與厚度兩邊都卡住。<br><br><b>小例子</b>（教材例題 1-2，數值為假設）：$2\\times10^{10}$ 顆電晶體、每顆漏 $1\\ \\text{nA}$、$V_{DD}=0.7\\ \\text{V}$，待機漏電 $14\\ \\text{W}$。SS 為 $66\\ \\text{mV/dec}$ 時把 $V_{th}$ 降 $0.1\\ \\text{V}$，倍數 $10^{100/66} \\approx 32.75$，漏電功耗變成約 $458.4\\ \\text{W}$。這就是為什麼晶片要準備多種臨界電壓的元件，只在關鍵路徑用低 $V_{th}$。<figure class=\"fig\"><img src=\"figs/fig_01_03_dennard_power_wall.svg\" alt=\"操作電壓與時脈在 2005 年後趨平，以及功率密度逼近散熱上限的對照圖\" loading=\"lazy\"><figcaption>約 2005 年後電源電壓觸底、單核時脈不再上升；如果沒有新材料、多核心與更好的散熱，功率密度早就超過散熱上限。</figcaption></figure>"
   },
   {
    "h": "換材料、換結構：把靜電控制搶回來",
    "b": "$$\\lambda_{\\text{SG}}=\\sqrt{\\frac{\\varepsilon_{\\text{si}}}{\\varepsilon_{ox}}t_{\\text{si}}t_{ox}},\\quad \\lambda_{\\text{DG}}=\\sqrt{\\frac{\\varepsilon_{\\text{si}}}{2\\varepsilon_{ox}}t_{\\text{si}}t_{ox}},\\quad \\lambda_{\\text{GAA}}=\\sqrt{\\frac{\\varepsilon_{\\text{si}}}{4\\varepsilon_{ox}}t_{\\text{si}}t_{ox}}$$<b>讀法</b>：λ 是汲極電場能滲進通道的距離。閘極包住的面越多，分母越大，λ 越短。經驗規則是閘極長度要大於約 $4\\lambda\\text{–}5\\lambda$，才壓得住短通道效應。<br><br><b>小例子</b>（教材 1.4.1 節）：$t_{\\text{si}} = 6\\ \\text{nm}$、$\\text{EOT} = 0.8\\ \\text{nm}$、$\\varepsilon_{\\text{si}}/\\varepsilon_{ox} = 11.7/3.9 = 3$。<ul><li>平面單閘極：$\\lambda = \\sqrt{14.4} \\approx 3.79\\ \\text{nm}$，最小 $L_g \\approx 4.5\\lambda \\approx 17.1\\ \\text{nm}$。</li><li>雙閘極（FinFET）：$\\lambda \\approx 2.68\\ \\text{nm}$，最小 $L_g \\approx 12.1\\ \\text{nm}$。</li><li>環繞式（GAA）：$\\lambda \\approx 1.90\\ \\text{nm}$，最小 $L_g \\approx 8.5\\ \\text{nm}$。</li></ul><b>依教材整理（2026）的技術狀態</b>：<table><tr><th>技術</th><th>狀態</th></tr><tr><td>應變矽（90 nm 起）、HKMG（45 nm 起）</td><td>已量產多年</td></tr><tr><td>FinFET（22 nm 到 3 nm）</td><td>已量產</td></tr><tr><td>GAA 奈米片（2 nm 等級）</td><td>教材寫 2025–2026 年進入量產</td></tr><tr><td>背面供電網路</td><td>教材寫 2025–2026 年開始導入</td></tr><tr><td>CFET（nMOS、pMOS 上下疊）</td><td>研發中，屬 2030 年代路線</td></tr></table><figure class=\"fig\"><img src=\"figs/fig_01_01_transistor_to_35d_evolution.jpg\" alt=\"從點接觸電晶體、平面 MOSFET、FinFET、GAA 奈米片到 3.5D 封裝的五代演進\" loading=\"lazy\"><figcaption>由左到右看閘極包住通道的面數越來越多，最後一格則把多顆晶片與記憶體堆疊在中介層上，代表微縮走到系統層級（示意圖，AI 生成）。</figcaption></figure>"
   },
   {
    "h": "產線與元件連結",
    "b": "<ul><li><b>多種臨界電壓元件</b>：先進製程在同一顆晶片上提供好幾檔 $V_{th}$，只有關鍵時序路徑用低 $V_{th}$，其他路徑用高 $V_{th}$ 鎖住漏電。要做出不同 $V_{th}$，靠的是 HKMG 的功函數金屬與摻雜，這會在第 3 集、第 10 集與第 11 集一路接上。</li><li><b>HKMG</b>：用 $\\mathrm{HfO_2}$（$k\\approx 20\\text{–}25$）取代 $\\mathrm{SiO_2}$（$k=3.9$），同樣的等效氧化層厚度下實體厚度可以厚約 $k/3.9 \\approx 5.1\\text{–}6.4$ 倍，閘極穿隧漏電大幅下降；金屬閘極也消除了多晶矽空乏效應。</li><li><b>背面供電與小晶片</b>：正面金屬層數多到十幾層後，電源線和訊號線搶空間、壓降也變大，所以把電源網路搬到晶圓背面（第 11 集）。另一頭，單一晶粒被光罩面積約 $858\\ \\text{mm}^2$ 卡住：以假設的 $220\\ \\text{MTr/mm}^2$ 計，一顆晶粒最多約 $858\\times 220\\times10^6 \\approx 1.89\\times 10^{11}$ 顆電晶體，要更多就得拆成小晶片再用 2.5D／3D 封裝組回來（第 15 集）。</li><li><b>產業分工</b>：整合元件製造廠、純晶圓代工、無晶圓廠設計公司、EDA／TCAD 軟體與設備材料商各司其職；一座先進 300 mm 晶圓廠投資已超過 200 億美元，超純水回收、溫室氣體減排也是製程工程師的日常（依教材整理，2026）。</li></ul>"
   },
   {
    "h": "常見陷阱",
    "b": "<ul><li><b>把節點名稱當成閘極長度</b>：「2 nm」「A16」「18A」是世代代號。依教材整理，先進節點的實體 $L_g$ 長期維持在約 $12\\text{–}16\\ \\text{nm}$，閘極間距約 $45\\text{–}48\\ \\text{nm}$、最小金屬間距約 $20\\text{–}26\\ \\text{nm}$。比較世代請看邏輯密度、間距與效能功耗面積（PPA）。</li><li><b>以為摩爾定律是物理定律</b>：它是經濟與技術一起維持的經驗規律。真正讓「縮小就更好」成立的是 Dennard 微縮，而它在電壓降不下去之後就失效了。</li><li><b>以為改善製程能讓 SS 低於 60 mV/dec</b>：只要電流是靠熱激發翻過能障，室溫下 SS 最低約 $59.5\\ \\text{mV/dec}$，這是 $k_BT/q$ 決定的。製程能做的是讓 $m$ 接近 1（更好的閘極控制），要突破這個下限得換電流機制。</li></ul>"
   },
   {
    "h": "對照教材",
    "b": "<ul><li><b>1.1 節</b>：矽勝出的三個理由，特別是 $\\mathrm{Si/SiO_2}$ 介面的低缺陷密度；也注意 SiC、GaN、SiGe、High-k 已經和矽共存。</li><li><b>1.2 節</b>：四個發明各解決了什麼瓶頸，以及 CMOS 的動態功耗式 $P_{\\text{dyn}} = \\alpha C_LV_{DD}^2f$。</li><li><b>1.3 節</b>：摩爾定律的 0.7 倍邏輯、Dennard 縮放表逐列推一次、SS 的推導，以及例題 1-1、1-2 的數字。</li><li><b>1.4 節</b>：應變矽、HKMG、FinFET、GAA、背面供電、CFET 各自的年代與狀態；節點命名的辨析；三種 λ 公式與最小閘極長度的估算。</li><li><b>1.5 節</b>：從 DTCO 到 STCO 的轉向、2.5D／3D 封裝為什麼被稱為第二條摩爾定律、產業分工與永續議題。</li><li><b>1.6 節</b>：整套教材四篇的分工，先知道後面每一站在地圖上的位置。</li></ul>"
   }
