    "b": "$$n_{\\text{Si}} = \\frac{8}{a^3},\\qquad \\sigma_{(100)} = \\frac{2}{a^2}$$<b>讀法</b>：一個邊長 $a$ 的立方晶胞裡有 8 顆矽原子，所以原子體積密度是 $8/a^3$；(100) 面上一個 $a\\times a$ 的方格裡等效有 2 顆原子。<br><br><b>小例子</b>：$a = 5.431\\ \\text{\\AA} = 5.431\\times10^{-8}\\ \\text{cm}$，得 $n_{\\text{Si}} = 4.99\\times10^{22}\\ \\text{cm}^{-3}$；再乘原子量 $28.085$、除以亞佛加厥常數，密度約 $2.33\\ \\text{g/cm}^3$；(100) 面原子密度 $6.78\\times10^{14}\\ \\text{cm}^{-2}$。<br><br><table><tr><th>晶面</th><th>表面原子密度（cm⁻²）</th><th>製程上的角色</th></tr><tr><td>(100)</td><td>$6.78\\times10^{14}$</td><td>CMOS 與 GAA 的標準基板：介面陷阱密度 $D_{it}$ 最低、電子遷移率最高</td></tr><tr><td>(110)</td><td>$9.59\\times10^{14}$</td><td>電洞遷移率最高；FinFET 的鰭片側壁就是這個面</td></tr><tr><td>(111)</td><td>$7.83\\times10^{14}$</td><td>熱氧化最快但 $D_{it}$ 高；傳統 GaN-on-Si 用它，因為六角對稱和 GaN 對得上</td></tr></table><br>缺陷依維度分四類：點缺陷（空位 $V$、自間隙原子 $I$，在熱平衡下一定存在，濃度隨溫度按阿瑞尼士關係上升）、差排、疊差與晶界、空洞與氧析出物。點缺陷是第 5 集擴散和第 8 集離子佈植的「搬運工」；其他缺陷落在主動區會造成漏電，所以 300 mm 晶錠要做到零差排。"
