    "b": "第 5 集的熱擴散有兩個硬傷：表面濃度永遠最高，深度和濃度綁在一起；而且要上千度，光阻撐不住，只能另做硬遮罩。現代電晶體要的是淺、濃、位置準的摻雜區。<br><br>離子佈植把兩件事拆開。劑量由法拉第杯積分束流算出來：$5\\ \\text{mA}$ 的 $\\mathrm{BF_2^+}$ 束打 $4.81\\ \\text{s}$，剛好在 $750\\ \\text{cm}^2$ 上放進 $2.0\\times10^{14}\\ \\text{cm}^{-2}$ 的硼，劑量可以控制在 $\\pm0.5\\%$ 以內，範圍橫跨 $10^{11}$ 到 $10^{16}\\ \\text{cm}^{-2}$。深度由加速能量決定。整個過程可以在室溫做，圖案化的光阻直接當遮罩。<br><br>能量要很低時又撞牆：要做深度小於 $10\\ \\text{nm}$ 的接面，硼得壓到 $0.2$ 到 $1\\ \\text{keV}$，這麼慢的單原子離子束會因為正電荷互相排斥而散掉。解法是改打分子離子，例如 $22.3\\ \\text{keV}$ 的 $\\mathrm{BF_2^+}$ 解離後，硼只分到 $22.3\\times11/49\\approx5.01\\ \\text{keV}$。"
