    "b": "<ul><li><b>MEOL 接觸插塞換金屬</b>：依教材整理（2026），10 nm 到 3 nm 世代的接觸插塞與部分 M0/M1 用鈷，次 2 nm 的局部互連開始用免阻障的釕、鉬；鉬也用在 3D NAND 字元線和先進 DRAM 位元線。實際上變成「混合金屬」：最底層用新金屬，M3 以上線寬較寬，仍是銅雙鑲嵌。</li><li><b>和前後站互相牽制</b>：雙鑲嵌的溝槽靠第 6 集的微影與第 9 集的蝕刻定義，阻障層和襯層要靠 PVD 或第 10 集的 ALD 鋪成只有幾奈米厚；電鍍後的過鍍銅要交給下一集的 CMP。後段溫度不能超過約 $400^\\circ\\text{C}$，所以這些步驟都要在低溫下完成。</li><li><b>晶背供電網路（BSPDN）</b>：正面供電時，電要從頂層一路穿過十幾層越來越細的導線才到電晶體，電源線又和訊號線搶 M0–M2 的空間。晶背供電的流程是：正面做完電晶體與訊號層 → 正面鍵合到載板晶圓 → 背面矽基板從 $775\\ \\mu\\text{m}$ 磨薄到數百奈米以下 → 從背面蝕刻奈米矽穿孔或直接做源極／汲極背面接觸 → 在背面做寬厚的供電金屬。依教材整理（2026），兩種代表架構是 Intel 18A 的 PowerVia（奈米矽穿孔接到正面 M0 或埋入式電源軌）與 TSMC A16 的 Super PowerRail（背面直接接觸源極／汲極），教材把它們列為 2025–2026 年間跨入量產的技術。</li></ul><b>小例子</b>（教材 TCAD 專欄的假設參數）：一個 $15\\ \\text{mA}$ 的電路區塊、$V_{DD} = 0.75\\ \\text{V}$，正面供電等效電阻 $5.20\\ \\Omega$，壓降 $78.0\\ \\text{mV}$（$V_{DD}$ 的 10.4%）；晶背供電等效電阻 $0.95\\ \\Omega$，壓降 $14.25\\ \\text{mV}$（1.9%），改善約 81.7%。<figure class=\"fig\"><img src=\"figs/fig_11_02_fs_vs_bspdn_interconnect.jpg\" alt=\"正面供電與晶背供電的互連剖面對照\" loading=\"lazy\"><figcaption>正面供電時電源和訊號擠在同一疊正面金屬層；晶背供電把粗大的電源網移到晶背，經奈米矽穿孔直達電晶體，正面只留訊號線。（示意圖，AI 生成）</figcaption></figure>"
