   {
    "h": "為什麼需要它",
    "b": "上一集的銅電鍍會在整片晶圓上留下 500–800 nm 的過鍍銅；每做完一層沉積和蝕刻，表面也會累積幾百奈米的高低起伏。問題在微影：景深 $\\text{DOF}\\propto\\lambda/\\text{NA}^2$，波長縮到 13.5 nm、NA 提到 0.55 後，景深只剩數十奈米。一個曝光場（$26\\times33\\ \\text{mm}^2$）內高台和凹谷差了幾百奈米，就不可能同時對焦。<br><br>直覺做法有三種，都撞牆：<ul><li><b>回流玻璃或旋塗玻璃</b>：只能撫平幾微米範圍內的小起伏，管不到晶片上毫米到公分尺度的圖案密度差。</li><li><b>純化學濕蝕刻</b>：凸處和凹處以相同速率下降。假設步階高 300 nm，蝕刻掉 200 nm 後步階還是 300 nm，一點也沒變平。</li><li><b>純機械研磨</b>：磨得平，但留下微刮傷和表層下的晶格損傷。</li></ul>CMP 把兩者合起來：化學先把表層幾奈米轉成鬆軟的修飾層，磨粒在壓力集中的凸處把它刮掉、露出新表面；凹處壓力小、保護層沒被磨破，移除就慢。凸處比凹處磨得快，步階才會一路縮小，最後達到全域平坦與 $R_a \\lt  0.2\\ \\text{nm}$ 的表面粗糙度。"
   },
   {
    "h": "機台與耗材",
    "b": "一台 300 mm 量產 CMP 機通常有三個研磨台（粗磨、清阻障層、精拋），再接一個研磨後清洗模組（PVA 海綿刷洗加兆聲波），避免磨粒乾掉黏死在晶圓上。<table><tr><th>零組件</th><th>做什麼</th><th>關鍵數字（依教材）</th></tr><tr><td>多區域膜片研磨頭</td><td>晶圓正面朝下，5–7 個同心氣室分區調整下壓力；外圍定位環補償邊緣應力集中</td><td>壓力精度 $0.05\\ \\text{psi}$，全片均勻度 1–2%</td></tr><tr><td>聚氨酯研磨墊</td><td>微孔與溝槽輸送磨液、帶走研屑</td><td>用久會釉化、速率暴跌</td></tr><tr><td>鑽石修整器</td><td>原位或片間微切墊面，維持表面微粗糙度</td><td>—</td></tr><tr><td>氧化物磨液</td><td>鹼性膠態 $\\mathrm{SiO_2}$，讓 Si–O–Si 鍵水合斷開</td><td>pH 10–11，粒徑 30–80 nm</td></tr><tr><td>STI 氧化鈰磨液</td><td>Ce–O–Si 鍵結快速移除氧化物，界面活性劑保護氮化矽</td><td>氧化物／氮化物選擇比 $\\gt  50:1$</td></tr><tr><td>銅磨液</td><td>$\\mathrm{H_2O_2}$ 氧化銅、甘胺酸溶解氧化銅、BTA 保護凹處</td><td>弱酸性或中性</td></tr></table><figure class=\"fig\"><img src=\"figs/fig_12_01_cmp_polisher_and_hb_recess.jpg\" alt=\"CMP 機台結構與混合鍵合銅墊凹陷剖面\" loading=\"lazy\"><figcaption>機台部分看研磨台、多區研磨頭、修整器和磨液怎麼配置；剖面部分比較過研磨造成的碟化、侵蝕，以及混合鍵合要的幾奈米銅墊凹陷。（示意圖，AI 生成）</figcaption></figure>"
   },
   {
    "h": "Preston 方程與等線速度",
    "b": "$$\\text{MRR}=K_p\\,P\\,V$$<b>讀法</b>：壓得越大、轉得越快，磨得越快；所有化學與耗材的影響都塞進 $K_p$。但這只在中低 $PV$ 成立。$PV$ 太高時，機械刮除快過化學生成軟化層的速度，移除率開始飽和：$$\\text{MRR}_{\\text{mod}}=\\frac{K_pPV}{1+\\beta PV}$$另一端，多孔低介電常數材料很脆，只能在 $1.0$–$2.5\\ \\text{psi}$ 的低壓視窗裡磨，以免分層。<br><br><b>怎麼讓整片晶圓磨得一樣快</b>：晶圓上一點相對研磨墊的速度是 $$\\mathbf{v}_{\\text{rel}}=(\\boldsymbol{\\omega}_p-\\boldsymbol{\\omega}_w)\\times\\mathbf{r}+\\boldsymbol{\\omega}_p\\times\\mathbf{d}$$只要研磨頭和研磨台同向、同角速度，第一項消失，每一點的速度都是 $V=\\omega_p d$，和半徑位置無關。實務上會讓兩者差 1–3 rpm，免得晶圓同一點一直掃過墊上同一個缺陷。<br><br><b>小例子</b>（教材例題 12-1）：<ol><li>$\\text{MRR}=115.0\\times2.5\\times1.2=345\\ \\text{nm/min}$。</li><li>磨掉 550 nm 過鍍銅要 $550/345=1.59\\ \\text{min}\\approx95.7\\ \\text{s}$。</li><li>研磨台 60 rpm 即 $2\\pi\\ \\text{rad/s}$，中心距 $d=1.2/2\\pi=0.191\\ \\text{m}=19.1\\ \\text{cm}$。加上晶圓半徑 15 cm，研磨台半徑至少要 34.1 cm，和約 76 cm 直徑的研磨台尺寸相符。</li></ol>"
   },
   {
    "h": "銅 CMP 三階段、碟化與侵蝕",
    "b": "銅雙鑲嵌的研磨分三個研磨台做：<ol><li><b>粗磨</b>：高移除率磨掉 500–800 nm 過鍍銅，剩約 50–100 nm 時由終點偵測切換。</li><li><b>軟著陸</b>：壓力降到 $1.5\\ \\text{psi}$ 以下、換低碟化磨液，把殘銅清乾淨並停在阻障層上（銅對 $\\mathrm{TaN}$ 選擇比 $\\gt  50:1$）。</li><li><b>阻障層與修整</b>：用對 $\\mathrm{TaN}$、銅、介電質選擇比接近 1:1:1 的磨液，磨掉阻障層並修平高低差。</li></ol>各處膜厚不完全一樣，第二階段要多磨 15–30%（過研磨）確保沒有殘銅短路。這段時間有彈性的研磨墊會微微陷進較軟的銅溝槽，產生兩種缺陷：<ul><li><b>碟化</b>：一條線中心凹下去。線越寬，墊越容易壓進去，深度約隨線寬對數增加；先進節點通常要求 $\\lt  20$–$25\\ \\text{nm}$。</li><li><b>侵蝕</b>：金屬密度 $\\rho_m=w/(w+s)$ 高的區域，撐住壓力的介電質只剩 $(1-\\rho_m)$，局部壓力放大成 $$P_{\\text{eff}}=\\frac{P}{1-\\rho_m}$$整片陣列一起被磨低。</li></ul><b>小例子</b>：$\\rho_m=0.8$ 時 $P_{\\text{eff}}=5P$；$\\rho_m=0.2$ 時是 $1.25P$，兩區壓力差 4 倍。<br><br>設計端的對策是兩條規則：寬導線中間切出介電質條（切槽），把連續銅寬限制在 $5$–$10\\ \\mu\\text{m}$ 以下；空曠處自動插入虛擬金屬，讓任何 $100\\times100\\ \\mu\\text{m}^2$ 視窗內的金屬密度落在 45%–55%。教材 TCAD 專欄用半經驗模型（25% 過研磨）算出：50 μm 寬電源線切成 5 μm 條，碟化從 49.1 降到 16.4 nm（少 66.6%）；高密匯流排的密度均化到 50%，侵蝕從 27.5 降到 10.0 nm（少 63.6%）。<figure class=\"fig\"><img src=\"figs/fig_12_02_preston_dishing_erosion.svg\" alt=\"Preston 移除速率曲線與碟化深度隨線寬和金屬密度變化\" loading=\"lazy\"><figcaption>先看移除速率在低壓區貼著 Preston 直線，高 PV 時彎向飽和；再看線越寬、金屬密度越高，碟化越深，說明均化密度與切槽的必要。</figcaption></figure>"
   },
   {
    "h": "混合鍵合的銅墊凹陷與晶背薄化",
    "b": "$$\\Delta h_{\\text{Cu}}=h_{\\text{Cu}}\\,(\\alpha_{\\text{Cu}}-\\alpha_{\\mathrm{SiO_2}})\\,\\Delta T$$<b>讀法</b>：退火時銅比氧化矽多膨脹多少，銅墊就相對凸出多少。混合鍵合要求室溫時銅墊不能凸出（否則介電質貼不上），又不能凹太深（否則加熱後碰不到）。介電質表面粗糙度要 $R_q\\lt 0.2\\ \\text{nm}$，任何幾十奈米的殘留磨粒都會撐出鍵合空洞。<br><br><b>小例子</b>（教材例題 12-2）：銅墊厚 1000 nm，$25\\to300^\\circ\\text{C}$，$\\Delta T=275\\ \\text{K}$。<ol><li>單側凸出 $1000\\times16\\times10^{-6}\\times275=4.40\\ \\text{nm}$，兩側合計 8.80 nm。</li><li>單側凹陷 2.0–3.5 nm 時，室溫縫隙 4.0–7.0 nm，加熱後還多出 1.8–4.8 nm 的壓縮量，讓銅擠在一起擴散融合。</li><li>單側凹陷超過 4.4 nm，膨脹後仍碰不到，開路；凹陷不到 1 nm 甚至凸出，膨脹過頭會撐開介電質鍵合面。</li></ol>整片晶圓上數千萬個銅墊的凹陷變異要控制在 $\\pm1\\ \\text{nm}$ 以內。<br><br><b>晶背薄化與終點偵測</b>：晶背供電要把背面矽從原本厚度磨到數百奈米，流程是粗磨 → 應力釋放 CMP → 選擇性濕蝕刻停在預埋的 $\\mathrm{SiGe}$ 或 SOI 埋氧層。停機靠多種原位終點偵測互相驗證：<table><tr><th>方法</th><th>原理</th><th>適合</th></tr><tr><td>渦電流</td><td>交變磁場在金屬膜感應渦電流，量不透明金屬厚度</td><td>銅粗磨階段的減速切換</td></tr><tr><td>寬頻光學頻譜</td><td>經墊上透明窗量薄膜干涉光譜</td><td>STI、層間介電質的殘餘厚度；阻障層清除時的反射率突變</td></tr><tr><td>馬達電流／摩擦力</td><td>換到不同材料時摩擦係數改變</td><td>輔助驗證</td></tr></table>"
   },
   {
    "h": "產線與元件連結",
    "b": "<ul><li><b>前段的 STI 與替代金屬閘極</b>：STI 用氧化鈰磨液、停在氮化矽上；在 FinFET 與 GAA 製程中，先磨出虛擬多晶矽閘極頂部，填入 $\\mathrm{HfO_2}$、功函數金屬與低阻金屬後再磨一次，決定閘極高度，均勻度要求 $\\pm1$–$2\\ \\text{nm}$，否則寄生電容與元件特性會跟著飄。</li><li><b>後段的新金屬</b>：上一集提到的釕很難氧化，強氧化劑又可能生成有毒且會揮發的 $\\mathrm{RuO_4}$。依教材整理（2026），釕的 CMP 靠調控 pH 的鹼性次氯酸鹽或過氧化氫配方，把表面轉成可研磨的固態 $\\mathrm{RuO_2}$ 水合層，同時避免和周圍材料形成電偶腐蝕。</li><li><b>三維堆疊與晶背供電</b>：混合鍵合用在第 15 集會講的三維異質整合與高頻寬記憶體堆疊，教材舉的例子是 TSMC SoIC-X 與 Intel Foveros Direct，垂直互連間距已推進到 $1\\ \\mu\\text{m}$ 以下；晶背供電的薄化也靠 CMP 加蝕刻停止層精準控厚。CMP 前接電鍍與沉積、後接微影，它留下的高低差直接吃掉下一層微影的景深。</li></ul>"
   },
   {
    "h": "常見陷阱",
    "b": "<ul><li><b>以為壓力加倍、速度加倍，移除率一定變四倍</b>：Preston 線性只在中低 $PV$ 成立；$PV$ 太高時化學軟化跟不上，移除率會飽和。而且低介電常數材料只能在 1.0–2.5 psi 的低壓視窗操作，加壓可能造成分層。</li><li><b>把碟化和侵蝕混為一談</b>：碟化是單一寬線中心凹陷，主要隨線寬變大，用切槽解決；侵蝕是高密度陣列整區被磨低，來自局部壓力 $P/(1-\\rho_m)$ 放大，用虛擬金屬填充均化密度解決。</li><li><b>以為混合鍵合的銅墊越平越好、最好齊平或凸一點</b>：凸出會讓介電質貼不上；正確做法是刻意留下幾奈米、而且全片一致的凹陷，讓退火膨脹剛好補滿。凹陷超過單側膨脹量（例題中 4.4 nm）就開路。</li></ul>"
   },
   {
    "h": "對照教材",
    "b": "<ul><li><b>12.1 節</b>：景深為什麼逼出全域平坦化；純化學、純機械各缺什麼；凸處優先移除的機制。</li><li><b>12.2 節</b>：研磨頭、研磨墊、修整器、三類磨液各自的角色；式（12.2）怎麼推出 $\\omega_w=\\omega_p$ 時速度均勻；飽和修正式（12.3）的意義。</li><li><b>12.3 節</b>：銅 CMP 三階段與過研磨；碟化、侵蝕的成因與 $P/(1-\\rho_m)$；切槽與虛擬金屬填充的規則；RMG 與釕、鉬 CMP 的難處。</li><li><b>12.4 節</b>：混合鍵合的表面粗糙度與 1–5 nm 凹陷視窗、式（12.4）；晶背薄化流程；三種終點偵測各適合哪個階段。</li><li><b>12.5–12.6 節</b>：自己重算兩題例題；看懂專欄模擬裡切槽與密度均化各降了多少碟化、侵蝕。</li></ul>"
   }
