    "b": "前面各集一站一站學了氧化、微影、蝕刻、沉積、金屬化和 CMP。可是一顆 2 nm 系統單晶片要走過 1,000 到 1,500 道步驟、花 2 到 3 個月，每一站都有自己的誤差和漂移，彼此還會牽制。<br><br>直覺做法是「每一站只要在規格內就好」。用教材例題 13-1 算給你看：閘極線寬規格 $14.00\\pm0.80\\ \\text{nm}$、$\\sigma = 0.22\\ \\text{nm}$。<ul><li>平均值對準 14.00 nm：$C_p = C_{pk} = 1.212$，不良率約 276.5 ppm。</li><li>腔壁累積副產物，平均值飄到 14.35 nm：每一片量出來仍「大多在規格內」，$C_p$ 也還是 1.212，但 $C_{pk}$ 掉到 0.682，不良率變成約 20,405 ppm，是原本的 73.8 倍。</li></ul>只盯著分佈寬度看不出這個問題。本集要建立三件事：流程怎麼排（熱預算與污染管制）、怎麼看見結構（線上量測與套準），以及怎麼用統計和回饋控制把漂移抓回來（SPC 與 APC）。"
