    "q": "電晶體底下如果不是一整塊矽，而是隔著一層很薄的氧化層，再往下才是矽，你猜會多出什麼用途？",
    "a": "通道底部被絕緣層截斷，深處的漏電路徑就沒了，通道也不必靠重摻雜去擋穿通。更有意思的是，底下那塊矽可以當成第二個閘極：加一個背面電壓，就能從下方推高或拉低臨界電壓，等於多了一個可以即時調整的旋鈕。"
