    "h": "產線與元件連結",
    "b": "<ul><li><b>前段製程整個重排</b>：GAA 把磊晶（超晶格）、蝕刻（高選擇比側向凹蝕與通道釋放）、ALD（內側間隙壁與環繞閘極）全部推到原子級精度；第 9、10 集的 ALE 與 ALD 就是為這一步準備的。</li><li><b>SRAM 的寬度問題</b>：FinFET 縮到單鰭後，SRAM 的單元比只能一格一格選；GAA 奈米片寬度可以連續調，等於替第 14 集的讀取穩定度問題多了一個設計自由度。</li><li><b>記憶體和封裝都用到混合鍵合</b>：3D NAND 的 CBA、HBM 的堆疊和邏輯晶片的 SoIC 都依賴第 12 集的混合鍵合 CMP——銅墊凹陷量要控制在奈米等級，否則接不起來。</li></ul>"
